// Get all incoming row items from the Google Sheets node
const items = $input.all();

// Configured file and sheet names
const fileName = "Students Report Data";
const sheetName = "Project / Task Status Report";

// Build dynamic subject line
const emailSubject = `${fileName} ${items.length} records processed`;

// Build clean HTML email body
let emailBody = `<h2>${fileName} - ${sheetName}</h2>`;
emailBody += `<p>Here is the latest data extracted from your Google Sheet:</p>`;
emailBody += `<table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; font-family: Arial, sans-serif;">`;

// Loop through each row
items.forEach((item, index) => {
  const row = { ...item.json };
  delete row.row_number; // Exclude row_number

  // Header row
  if (index === 0) {
    emailBody += `<tr style="background-color: #f2f2f2;">`;
    Object.keys(row).forEach(key => {
      emailBody += `<th>${key}</th>`;
    });
    emailBody += `</tr>`;
  }

  // Data rows
  emailBody += `<tr>`;
  Object.values(row).forEach(val => {
    emailBody += `<td>${val ?? ''}</td>`;
  });
  emailBody += `</tr>`;
});

emailBody += `</table>`;
emailBody += `<br><br>`;
emailBody += `<p style="margin: 0; font-family: Arial, sans-serif;">Regards,</p>`;
emailBody += `<p style="margin: 0; font-weight: bold; font-family: Arial, sans-serif;">GS Automation</p>`;

// Return formatted subject and HTML body
return [
  {
    json: {
      emailSubject: emailSubject,
      emailHtml: emailBody
    }
  }
];
